//! Real host/tool/store integration driven by a deterministic local provider.
//!
//! CSV bytes are generated by the production write_file tool. PDF/PPTX bytes
//! are declared repository fixtures; this verifies delivery and persistence,
//! not a real language model or a professional document generator.

use std::fs;
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use serde_json::{Value, json};

use crate::{AgentHandle, ChatLine, LlmConfig, SessionOrigin, TurnStatus};

const CSV: &str = "region,sales\nNorth,120\nSouth,80\n";
const SUBMISSION: u128 = 0x1234;

struct Scratch(PathBuf);

impl Scratch {
    fn new() -> Self {
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "flowy-artifact-integration-{}-{stamp}",
            std::process::id()
        ));
        fs::create_dir_all(&root).unwrap();
        Self(root)
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

struct ProviderFixture {
    address: std::net::SocketAddr,
    stopped: Arc<AtomicBool>,
    phase: Arc<AtomicUsize>,
    output_root: Arc<Mutex<Option<PathBuf>>>,
    requests: Arc<Mutex<Vec<Value>>>,
    thread: Option<thread::JoinHandle<()>>,
}

impl ProviderFixture {
    fn start() -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        listener.set_nonblocking(true).unwrap();
        let stopped = Arc::new(AtomicBool::new(false));
        let phase = Arc::new(AtomicUsize::new(0));
        let output_root = Arc::new(Mutex::new(None::<PathBuf>));
        let requests = Arc::new(Mutex::new(Vec::new()));
        let state = (
            Arc::clone(&stopped),
            Arc::clone(&phase),
            Arc::clone(&output_root),
            Arc::clone(&requests),
        );
        let thread = thread::spawn(move || {
            while !state.0.load(Ordering::SeqCst) {
                match listener.accept() {
                    Ok((mut socket, _)) => {
                        if state.0.load(Ordering::SeqCst) {
                            break;
                        }
                        // Windows accepted sockets inherit the listener's
                        // nonblocking mode. Restore blocking I/O before the
                        // bounded request read, otherwise a request accepted
                        // just before its bytes arrive is mistaken for EOF.
                        socket.set_nonblocking(false).unwrap();
                        let Some(request) = read_request(&mut socket) else {
                            continue;
                        };
                        let has_tools = request["tools"]
                            .as_array()
                            .is_some_and(|tools| !tools.is_empty());
                        state.3.lock().unwrap().push(request);
                        let (delta, finish_reason) = if has_tools {
                            let index = state.1.fetch_add(1, Ordering::SeqCst);
                            let root = state
                                .2
                                .lock()
                                .unwrap()
                                .clone()
                                .expect("host assigned output root");
                            match index {
                                0 => tool_delta(
                                    "fixture-write-csv",
                                    "write_file",
                                    json!({
                                        "path": root.join("sales.csv").display().to_string(), "content": CSV
                                    }),
                                ),
                                1 => tool_delta(
                                    "fixture-publish-csv",
                                    "publish_file",
                                    json!({
                                        "path": "sales.csv", "delivery_key": "sales", "display_name": "Sales report.csv"
                                    }),
                                ),
                                2 => tool_delta(
                                    "fixture-publish-pdf",
                                    "publish_file",
                                    json!({
                                        "path": "sample.pdf", "delivery_key": "pdf-fixture"
                                    }),
                                ),
                                3 => tool_delta(
                                    "fixture-publish-pptx",
                                    "publish_file",
                                    json!({
                                        "path": "sample.pptx", "delivery_key": "pptx-fixture"
                                    }),
                                ),
                                _ => (
                                    json!({"role":"assistant","content":"Fixture delivery complete."}),
                                    "stop",
                                ),
                            }
                        } else {
                            // Automatic conversation-title requests are
                            // independent of the actual delivery turn.
                            (
                                json!({"role":"assistant","content":"Artifact fixture delivery"}),
                                "stop",
                            )
                        };
                        let _ = write_stream(&mut socket, delta, finish_reason);
                    }
                    Err(error)
                        if error.kind() == std::io::ErrorKind::WouldBlock =>
                    {
                        thread::sleep(Duration::from_millis(5))
                    }
                    Err(error) => {
                        panic!("local fixture provider failed: {error}")
                    }
                }
            }
        });
        Self {
            address,
            stopped,
            phase,
            output_root,
            requests,
            thread: Some(thread),
        }
    }

    fn config(&self) -> LlmConfig {
        LlmConfig {
            api_key: Some("isolated-integration-fixture-token".into()),
            provider: "openai".into(),
            model: "fixture-delivery-model".into(),
            base_url: format!("http://{}/v1", self.address),
            ..LlmConfig::default()
        }
    }
}

impl Drop for ProviderFixture {
    fn drop(&mut self) {
        self.stopped.store(true, Ordering::SeqCst);
        let _ = TcpStream::connect(self.address);
        if let Some(thread) = self.thread.take() {
            thread.join().unwrap();
        }
    }
}

fn tool_delta(
    call_id: &str,
    name: &str,
    arguments: Value,
) -> (Value, &'static str) {
    (
        json!({
            "role": "assistant",
            "tool_calls": [{
                "index": 0, "id": call_id, "type": "function",
                "function": { "name": name, "arguments": arguments.to_string() }
            }]
        }),
        "tool_calls",
    )
}

fn read_request(socket: &mut TcpStream) -> Option<Value> {
    socket.set_read_timeout(Some(Duration::from_secs(5))).ok()?;
    let mut bytes = Vec::new();
    let header_end = loop {
        if let Some(index) =
            bytes.windows(4).position(|window| window == b"\r\n\r\n")
        {
            break index + 4;
        }
        assert!(
            bytes.len() < 2 * 1024 * 1024,
            "fixture request exceeded its limit"
        );
        let mut buffer = [0_u8; 4096];
        let read = socket.read(&mut buffer).ok()?;
        if read == 0 {
            return None;
        }
        bytes.extend_from_slice(&buffer[..read]);
    };
    let headers = std::str::from_utf8(&bytes[..header_end]).ok()?;
    let length = headers.lines().find_map(|line| {
        let (name, value) = line.split_once(':')?;
        if name.eq_ignore_ascii_case("content-length") {
            value.trim().parse::<usize>().ok()
        } else {
            None
        }
    })?;
    assert!(length < 2 * 1024 * 1024, "fixture body exceeded its limit");
    while bytes.len() < header_end + length {
        let mut buffer = [0_u8; 4096];
        let read = socket.read(&mut buffer).ok()?;
        if read == 0 {
            return None;
        }
        bytes.extend_from_slice(&buffer[..read]);
    }
    serde_json::from_slice(&bytes[header_end..header_end + length]).ok()
}

fn write_stream(
    socket: &mut TcpStream,
    delta: Value,
    finish_reason: &str,
) -> std::io::Result<()> {
    let delta = json!({
        "id":"fixture-response", "object":"chat.completion.chunk", "created":1,
        "model":"fixture-delivery-model", "choices":[{"index":0,"delta":delta,"finish_reason":null}]
    });
    let finished = json!({
        "id":"fixture-response", "object":"chat.completion.chunk", "created":1,
        "model":"fixture-delivery-model", "choices":[{"index":0,"delta":{},"finish_reason":finish_reason}]
    });
    let body = format!("data: {delta}\n\ndata: {finished}\n\ndata: [DONE]\n\n");
    let headers = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        body.len()
    );
    socket.write_all(headers.as_bytes())?;
    socket.write_all(body.as_bytes())?;
    socket.flush()
}

fn wait_for_completion(
    handle: &AgentHandle,
    provider: &ProviderFixture,
    root: &std::path::Path,
    session: &str,
) {
    let deadline = Instant::now() + Duration::from_secs(15);
    while handle.turn_status().is_busy() && Instant::now() < deadline {
        thread::sleep(Duration::from_millis(10));
    }
    assert_eq!(
        handle.turn_status(),
        TurnStatus::Completed,
        "host turn failed: {:?}; durable core status: {:?}; scripted requests: {:?}",
        handle.lines(),
        flowy_agent_core::SessionIndex::load(root).map(|history| history
            .get(session)
            .map(|record| record.status.clone())),
        provider
            .requests
            .lock()
            .unwrap()
            .iter()
            .map(|request| json!({
                "model": request["model"],
                "messages": request["messages"],
                "tool_count": request["tools"].as_array().map_or(0, Vec::len)
            }))
            .collect::<Vec<_>>()
    );
    assert!(provider.phase.load(Ordering::SeqCst) >= 5);
}

fn artifact_ids(handle: &AgentHandle) -> Vec<String> {
    handle
        .lines()
        .into_iter()
        .filter_map(|line| {
            if let ChatLine::Artifact { artifact_id } = line {
                Some(artifact_id)
            } else {
                None
            }
        })
        .collect()
}

#[test]
fn scripted_host_delivers_real_csv_and_document_fixtures_through_publish_file()
{
    let scratch = Scratch::new();
    let provider = ProviderFixture::start();
    let handle = AgentHandle::with_config(scratch.0.clone(), provider.config());
    let session = handle.create_home_session().unwrap();
    let history = flowy_agent_core::SessionIndex::load(&scratch.0).unwrap();
    let record = history.get(&session).unwrap();
    assert_eq!(record.origin, SessionOrigin::Home);
    let output = record
        .workspace
        .as_ref()
        .unwrap()
        .root
        .join("outputs")
        .join(format!("submission-{SUBMISSION:032x}"));
    fs::create_dir_all(&output).unwrap();
    *provider.output_root.lock().unwrap() = Some(output.clone());
    let fixtures = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../flowy-studio/examples/fixtures/preview");
    let pdf = fs::read(fixtures.join("sample.pdf")).unwrap();
    let pptx = fs::read(fixtures.join("sample.pptx")).unwrap();
    assert!(pdf.starts_with(b"%PDF-"));
    assert!(pptx.starts_with(b"PK\x03\x04"));
    fs::write(output.join("sample.pdf"), &pdf).unwrap();
    fs::write(output.join("sample.pptx"), &pptx).unwrap();

    handle.submit_chat(SUBMISSION, "Create the sales CSV and publish it with the declared PDF and PPTX fixtures.").unwrap();
    wait_for_completion(&handle, &provider, &scratch.0, &session);
    let ids = artifact_ids(&handle);
    assert_eq!(
        ids.len(),
        3,
        "the three real publish calls must produce three cards"
    );
    let store = handle.artifact_store().unwrap();
    let artifacts = store.list().unwrap();
    assert_eq!(artifacts.len(), 3);
    let mut expected = std::collections::BTreeMap::from([
        ("Sales report.csv", CSV.as_bytes().to_vec()),
        ("sample.pdf", pdf),
        ("sample.pptx", pptx),
    ]);
    for artifact in &artifacts {
        let receipt = &artifact.manifest.receipt;
        assert_eq!(receipt.session_id, session);
        assert!(ids.contains(&receipt.artifact_id));
        let bytes = expected.remove(receipt.display_name.as_str()).unwrap();
        assert_eq!(store.read_payload(&receipt.artifact_id).unwrap(), bytes);
    }
    assert!(expected.is_empty());
    let csv_id = artifacts
        .iter()
        .find(|artifact| {
            artifact.manifest.receipt.display_name == "Sales report.csv"
        })
        .unwrap()
        .manifest
        .receipt
        .artifact_id
        .clone();
    let original_receipt =
        store.get(&csv_id).unwrap().unwrap().manifest.receipt;
    store.set_favorite(&csv_id, true).unwrap();
    store.trash(&csv_id).unwrap();

    fs::write(output.join("sales.csv"), b"later overwritten source").unwrap();
    fs::remove_file(output.join("sample.pdf")).unwrap();
    assert_eq!(store.read_payload(&csv_id).unwrap(), CSV.as_bytes());
    assert_eq!(
        store.get(&csv_id).unwrap().unwrap().manifest.receipt.sha256,
        original_receipt.sha256
    );
    let export = scratch.0.join("saved-report.csv");
    store.copy_to(&csv_id, &export).unwrap();
    assert_eq!(fs::read(export).unwrap(), CSV.as_bytes());
    drop(store);
    drop(handle);
    drop(provider);

    let restored =
        AgentHandle::with_config(scratch.0.clone(), LlmConfig::default());
    restored.select_session(&session).unwrap();
    assert_eq!(artifact_ids(&restored), ids);
    let store = restored.artifact_store().unwrap();
    let favorite = store.get(&csv_id).unwrap().unwrap();
    assert!(favorite.preference.favorite);
    assert!(favorite.preference.trashed_at_ms.is_some());
    store.restore_from_trash(&csv_id).unwrap();
    assert_eq!(store.read_payload(&csv_id).unwrap(), CSV.as_bytes());
    restored.delete_session(&session).unwrap();
    assert!(restored.source_deleted(&session));
    assert!(!restored.source_available(&session));
    assert_eq!(store.list().unwrap().len(), 3);
    assert_eq!(store.read_payload(&csv_id).unwrap(), CSV.as_bytes());
    drop(restored);

    let reopened =
        AgentHandle::with_config(scratch.0.clone(), LlmConfig::default());
    assert!(reopened.source_deleted(&session));
    assert!(reopened.list_sessions().is_empty());
    let store = reopened.artifact_store().unwrap();
    assert_eq!(store.list().unwrap().len(), 3);
    assert_eq!(store.read_payload(&csv_id).unwrap(), CSV.as_bytes());
}
